// Gisement - AgentCore Policy (Cedar), generated from gisement.politique.regles.
// Do not edit by hand: the registry is the single source of truth.
// Cedar is deny by default - what is not permitted here is refused.

// regle_k5
forbid (principal, action == Action::"Mesure__agregat", resource)
  when { !context.has("taille_groupe") || context.taille_groupe < 5 };

// regle_individu
forbid (principal, action == Action::"Mesure__agregat", resource)
  when { context.groupements.containsAny(["individu", "personne", "salarie", "employe", "pseudonyme", "pseudo", "matricule", "nom", "prenom", "email", "poste"]) };

// regle_citation
forbid (principal, action == Action::"Mesure__agregat", resource)
  when { context.citations == true || context.sortie.containsAny(["citation_non_agregee", "classement_individuel", "score_individuel", "temps_travail_individuel"]) };

// regle_filtre_personne
forbid (principal, action == Action::"Mesure__agregat", resource)
  when { context.filtres.containsAny(["individu", "personne", "salarie", "employe", "pseudonyme", "pseudo", "matricule", "nom", "prenom", "email", "telephone"]) };

// regle_attribut_rare
forbid (principal, action == Action::"Mesure__agregat", resource)
  when { context.filtres.containsAny(["langue_parlee", "temps_partiel", "jour_travaille", "anciennete", "date_naissance", "commune_domicile", "vehicule", "badge", "poste_telephonique", "adresse_ip"]) };

// regle_combinaison
forbid (principal, action == Action::"Mesure__agregat", resource)
  when { context.nb_filtres >= 3 && context.taille_resultat_apres_filtres < 5 };

// regle_canal_non_autorise
forbid (principal, action == Action::"Mesure__agregat", resource)
  when { !context.canaux_autorises.contains(context.canal) };

// regle_conformite
forbid (principal, action, resource)
  when { context.conforme == false };

// regle_suspension
forbid (principal, action, resource)
  when { context.suspendue == true };

// regle_budget
forbid (principal, action, resource)
  when { context.budget_restant <= 0 };

// regle_quota_requetes
forbid (principal, action, resource)
  when { context.requetes_utilisateur > 200 };

// regle_tenant
forbid (principal, action, resource)
  when { principal.tenant != resource.tenant };

// regle_corpus_brut
forbid (principal, action == Action::"Corpus__lire", resource)
  when { context.corpus_assaini == false };

// regle_export
forbid (principal, action == Action::"Export__produire", resource)
  when { context.citations == true || context.taille_groupe < 5 };

permit (principal in Role::"commanditaire", action == Action::"Mesure__agregat", resource)
  when { context.conforme == true && context.suspendue == false
          && context.taille_groupe >= 5 && context.budget_restant > 0 };

permit (principal in Role::"responsable_service", action == Action::"Mesure__agregat", resource)
  when { context.conforme == true && context.suspendue == false
          && context.taille_groupe >= 5 && context.budget_restant > 0 };

permit (principal in Role::"dpo", action == Action::"Mesure__agregat", resource)
  when { context.conforme == true && context.suspendue == false
          && context.taille_groupe >= 5 && context.budget_restant > 0 };

permit (principal in Role::"consultant_msp", action == Action::"Mesure__agregat", resource)
  when { context.conforme == true && context.suspendue == false
          && context.taille_groupe >= 5 && context.budget_restant > 0 };

permit (principal in Role::"responsable_compte", action == Action::"Mesure__agregat", resource)
  when { context.conforme == true && context.suspendue == false
          && context.taille_groupe >= 5 && context.budget_restant > 0 };

